def parse_csv(text: str) -> list[list[str]]:
    """BUGGY: naive split breaks on quoted commas, escaped quotes, and embedded newlines."""
    rows = []
    for line in text.splitlines():
        if not line:
            continue
        rows.append([cell.strip('"') for cell in line.split(',')])
    return rows

