import time


class LruTtlCache:
    """BUGGY: does not refresh recency on get/put and evicts live items before expired ones."""

    def __init__(self, capacity: int, clock=time.monotonic):
        self.capacity = capacity
        self.clock = clock
        self._store: dict = {}

    def get(self, key):
        item = self._store.get(key)
        if item is None:
            return None
        val, exp = item
        if self.clock() >= exp:
            del self._store[key]
            return None
        return val

    def put(self, key, value, ttl: float) -> None:
        if len(self._store) >= self.capacity and key not in self._store:
            oldest = next(iter(self._store))
            del self._store[oldest]
        self._store[key] = (value, self.clock() + ttl)

    def __len__(self) -> int:
        return len(self._store)

