def compare_semver(a: str, b: str) -> int:
    """BUGGY: compares prerelease lexically and fails to ignore build metadata."""
    def key(v: str):
        main, *rest = v.split('-', 1)
        nums = tuple(int(x) for x in main.split('.'))
        pre = rest[0] if rest else ''
        return (nums, pre)
    ka, kb = key(a), key(b)
    return (ka > kb) - (ka < kb)


def sort_versions(versions: list[str]) -> list[str]:
    from functools import cmp_to_key
    return sorted(versions, key=cmp_to_key(compare_semver))

