import copy


def _resolve_parent(doc, path: str):
    parts = path.lstrip('/').split('/')
    cur = doc
    for p in parts[:-1]:
        cur = cur[int(p)] if isinstance(cur, list) else cur[p]
    return cur, parts[-1]


def apply_patch(doc, ops: list[dict]):
    """BUGGY: no ~0/~1 unescaping, no '-' append, no strict bool/int test, no move cycle check."""
    out = copy.deepcopy(doc)
    for op in ops:
        kind = op['op']
        parent, key = _resolve_parent(out, op['path'])
        if kind == 'add':
            if isinstance(parent, list):
                parent.insert(int(key), op['value'])
            else:
                parent[key] = op['value']
        elif kind == 'remove':
            if isinstance(parent, list):
                parent.pop(int(key))
            else:
                del parent[key]
        elif kind == 'replace':
            if isinstance(parent, list):
                parent[int(key)] = op['value']
            else:
                parent[key] = op['value']
        elif kind == 'test':
            actual = parent[int(key)] if isinstance(parent, list) else parent[key]
            if actual != op['value']:
                raise ValueError('test failed')
        else:
            raise ValueError(f'unsupported op: {kind}')
    return out

