import unittest
from json_patch import apply_patch


class TestJsonPatch(unittest.TestCase):
    def test_pointer_escaping(self):
        doc = {'a/b': {'c~d': 1}}
        res = apply_patch(doc, [{'op': 'replace', 'path': '/a~1b/c~0d', 'value': 2}])
        self.assertEqual(res, {'a/b': {'c~d': 2}})

    def test_array_append_dash(self):
        doc = {'items': [1, 2]}
        res = apply_patch(doc, [{'op': 'add', 'path': '/items/-', 'value': 3}])
        self.assertEqual(res['items'], [1, 2, 3])

    def test_move_and_copy(self):
        doc = {'a': {'x': 10}, 'b': {}}
        res = apply_patch(doc, [
            {'op': 'copy', 'from': '/a/x', 'path': '/b/y'},
            {'op': 'move', 'from': '/a/x', 'path': '/b/z'},
        ])
        self.assertEqual(res, {'a': {}, 'b': {'y': 10, 'z': 10}})

    def test_move_into_descendant_rejected(self):
        doc = {'a': {'b': {'c': 1}}}
        with self.assertRaises(ValueError):
            apply_patch(doc, [{'op': 'move', 'from': '/a/b', 'path': '/a/b/c/d'}])

    def test_strict_bool_vs_int(self):
        doc = {'flag': True, 'num': 1}
        with self.assertRaises(ValueError):
            apply_patch(doc, [{'op': 'test', 'path': '/flag', 'value': 1}])
        with self.assertRaises(ValueError):
            apply_patch(doc, [{'op': 'test', 'path': '/num', 'value': True}])
        res = apply_patch(doc, [{'op': 'test', 'path': '/flag', 'value': True}])
        self.assertEqual(res, doc)


if __name__ == '__main__':
    unittest.main()

