def summarize_logs(records: list[tuple[str, str]], top_k: int = 5) -> list[dict]:
    """BUGGY (O(N^2)): linear scan for unique users and repeated sorts."""
    endpoints = []
    for ep, _ in records:
        if ep not in endpoints:
            endpoints.append(ep)
    summary = []
    for ep in endpoints:
        count = 0
        users = []
        for r_ep, user in records:
            if r_ep == ep:
                count += 1
                if user not in users:
                    users.append(user)
        summary.append({'endpoint': ep, 'count': count, 'unique_users': len(users)})
    summary.sort(key=lambda d: (-d['count'], d['endpoint']))
    return summary[:top_k]

