pub struct RingBuffer<T> {
    buf: Vec<Option<T>>,
    head: usize,
    len: usize,
}

impl<T> RingBuffer<T> {
    pub fn new(cap: usize) -> Self {
        assert!(cap > 0, "capacity must be > 0");
        let mut buf = Vec::with_capacity(cap);
        buf.resize_with(cap, || None);
        Self { buf, head: 0, len: 0 }
    }

    pub fn len(&self) -> usize { self.len }
    pub fn is_empty(&self) -> bool { self.len == 0 }
    pub fn capacity(&self) -> usize { self.buf.len() }

    /// BUGGY: fails to advance head on overwrite and drops wrong slot.
    pub fn push_overwrite(&mut self, val: T) -> Option<T> {
        let cap = self.buf.len();
        let tail = (self.head + self.len) % cap;
        let prev = self.buf[tail].replace(val);
        if self.len < cap {
            self.len += 1;
        }
        prev
    }

    pub fn pop(&mut self) -> Option<T> {
        if self.len == 0 { return None; }
        let val = self.buf[self.head].take();
        self.head = (self.head + 1) % self.buf.len();
        self.len -= 1;
        val
    }

    /// BUGGY: ignores head offset and yields in raw storage order.
    pub fn iter(&self) -> Vec<&T> {
        self.buf.iter().filter_map(|x| x.as_ref()).collect()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn overwrite_and_order() {
        let mut rb = RingBuffer::new(3);
        assert_eq!(rb.push_overwrite(1), None);
        assert_eq!(rb.push_overwrite(2), None);
        assert_eq!(rb.push_overwrite(3), None);
        assert_eq!(rb.push_overwrite(4), Some(1));
        assert_eq!(rb.push_overwrite(5), Some(2));
        assert_eq!(rb.len(), 3);
        assert_eq!(rb.iter(), vec![&3, &4, &5]);
        assert_eq!(rb.pop(), Some(3));
        assert_eq!(rb.pop(), Some(4));
        assert_eq!(rb.pop(), Some(5));
        assert_eq!(rb.pop(), None);
    }

    #[test]
    fn wraparound_after_pops() {
        let mut rb = RingBuffer::new(3);
        rb.push_overwrite(10);
        rb.push_overwrite(20);
        assert_eq!(rb.pop(), Some(10));
        rb.push_overwrite(30);
        rb.push_overwrite(40);
        assert_eq!(rb.iter(), vec![&20, &30, &40]);
        assert_eq!(rb.push_overwrite(50), Some(20));
        assert_eq!(rb.iter(), vec![&30, &40, &50]);
    }
}

