use std::collections::BTreeMap;
use std::fs::{File, OpenOptions};
use std::io::{Read, Write};
use std::path::{Path, PathBuf};

pub fn fnv1a32(bytes: &[u8]) -> u32 {
    let mut h: u32 = 0x811c_9dc5;
    for &b in bytes {
        h ^= b as u32;
        h = h.wrapping_mul(0x0100_0193);
    }
    h
}

pub struct Wal {
    path: PathBuf,
    pub map: BTreeMap<String, String>,
}

impl Wal {
    /// BUGGY: fails with Err on torn tail instead of recovering & truncating.
    pub fn recover(path: &Path) -> std::io::Result<Self> {
        let mut map = BTreeMap::new();
        if path.exists() {
            let mut data = Vec::new();
            File::open(path)?.read_to_end(&mut data)?;
            let mut off = 0;
            while off < data.len() {
                let len = u32::from_le_bytes(data[off..off + 4].try_into().unwrap()) as usize;
                let _crc = u32::from_le_bytes(data[off + 4..off + 8].try_into().unwrap());
                let payload = &data[off + 8..off + 8 + len];
                let line = std::str::from_utf8(payload).unwrap();
                if let Some((k, v)) = line.split_once('=') {
                    map.insert(k.to_string(), v.to_string());
                }
                off += 8 + len;
            }
        }
        Ok(Self { path: path.to_path_buf(), map })
    }

    pub fn put(&mut self, key: &str, val: &str) -> std::io::Result<()> {
        let payload = format!("{key}={val}");
        let bytes = payload.as_bytes();
        let len = bytes.len() as u32;
        let crc = fnv1a32(bytes);
        let mut f = OpenOptions::new().create(true).append(true).open(&self.path)?;
        f.write_all(&len.to_le_bytes())?;
        f.write_all(&crc.to_le_bytes())?;
        f.write_all(bytes)?;
        f.flush()?;
        self.map.insert(key.to_string(), val.to_string());
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::fs;

    #[test]
    fn recovers_from_torn_tail_and_appends() {
        let path = std::env::temp_dir().join(format!("kv_wal_test_{}.wal", std::process::id()));
        let _ = fs::remove_file(&path);
        {
            let mut w = Wal::recover(&path).unwrap();
            w.put("k1", "v1").unwrap();
            w.put("k2", "v2").unwrap();
        }
        // Append a torn tail (header claims 100 bytes, only 3 bytes present)
        {
            let mut f = OpenOptions::new().append(true).open(&path).unwrap();
            f.write_all(&100u32.to_le_bytes()).unwrap();
            f.write_all(&0u32.to_le_bytes()).unwrap();
            f.write_all(b"abc").unwrap();
        }
        let mut w2 = Wal::recover(&path).unwrap();
        assert_eq!(w2.map.get("k1").map(String::as_str), Some("v1"));
        assert_eq!(w2.map.get("k2").map(String::as_str), Some("v2"));
        assert_eq!(w2.map.len(), 2);
        // Appending after recovery must produce a clean WAL
        w2.put("k3", "v3").unwrap();
        let w3 = Wal::recover(&path).unwrap();
        assert_eq!(w3.map.get("k3").map(String::as_str), Some("v3"));
        let _ = fs::remove_file(&path);
    }

    #[test]
    fn rejects_bad_checksum_tail() {
        let path = std::env::temp_dir().join(format!("kv_wal_crc_{}.wal", std::process::id()));
        let _ = fs::remove_file(&path);
        {
            let mut w = Wal::recover(&path).unwrap();
            w.put("good", "yes").unwrap();
        }
        {
            let mut f = OpenOptions::new().append(true).open(&path).unwrap();
            let bad = b"bad=no";
            f.write_all(&(bad.len() as u32).to_le_bytes()).unwrap();
            f.write_all(&0xdead_beefu32.to_le_bytes()).unwrap();
            f.write_all(bad).unwrap();
        }
        let w = Wal::recover(&path).unwrap();
        assert_eq!(w.map.get("good").map(String::as_str), Some("yes"));
        assert!(!w.map.contains_key("bad"));
        let _ = fs::remove_file(&path);
    }
}

use std::sync::{mpsc, Arc, Mutex};
use std::thread;

/// BUGGY: deadlocks because `res_tx` is never dropped, and output order is nondeterministic.
pub fn parallel_map<F>(items: Vec<i64>, workers: usize, f: F) -> Vec<i64>
where
    F: Fn(i64) -> i64 + Send + Sync + 'static,
{
    let (work_tx, work_rx) = mpsc::channel::<i64>();
    let work_rx = Arc::new(Mutex::new(work_rx));
    let (res_tx, res_rx) = mpsc::channel::<i64>();
    let f = Arc::new(f);

    for item in items {
        work_tx.send(item).unwrap();
    }
    // BUG: work_tx and res_tx are never dropped!
    let mut handles = Vec::new();
    for _ in 0..workers {
        let rx = Arc::clone(&work_rx);
        let tx = res_tx.clone();
        let f = Arc::clone(&f);
        handles.push(thread::spawn(move || {
            while let Ok(v) = rx.lock().unwrap().recv() {
                tx.send(f(v)).unwrap();
            }
        }));
    }
    let mut out = Vec::new();
    for r in res_rx {
        out.push(r);
    }
    for h in handles {
        h.join().unwrap();
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::time::Duration;

    #[test]
    fn preserves_order_and_terminates() {
        let (done_tx, done_rx) = mpsc::channel();
        thread::spawn(move || {
            let res = parallel_map((1..=20).collect(), 4, |x| x * x);
            let _ = done_tx.send(res);
        });
        let res = done_rx
            .recv_timeout(Duration::from_secs(3))
            .expect("parallel_map deadlocked!");
        let expected: Vec<i64> = (1..=20).map(|x| x * x).collect();
        assert_eq!(res, expected);
    }

    #[test]
    fn handles_empty_and_zero_workers() {
        let (tx, rx) = mpsc::channel();
        thread::spawn(move || {
            let a = parallel_map(vec![], 4, |x| x + 1);
            let b = parallel_map(vec![3, 4], 0, |x| x * 2);
            let _ = tx.send((a, b));
        });
        let (a, b) = rx
            .recv_timeout(Duration::from_secs(2))
            .expect("parallel_map deadlocked on empty/zero workers!");
        assert_eq!(a, Vec::<i64>::new());
        assert_eq!(b, vec![6, 8]);
    }
}

