import json
import os
import subprocess
import sys
import tempfile
import unittest
from merger import deep_merge


class TestConfigMerge(unittest.TestCase):
    def test_deep_merge_nested_dicts(self):
        base = {'db': {'host': 'localhost', 'port': 5432}, 'tags': ['a']}
        over = {'db': {'port': 5433, 'ssl': True}, 'tags': ['b']}
        res = deep_merge(base, over)
        self.assertEqual(res, {'db': {'host': 'localhost', 'port': 5433, 'ssl': True}, 'tags': ['b']})
        # Must not mutate inputs
        self.assertEqual(base['db']['port'], 5432)

    def test_concat_arrays_and_delete_null_cli(self):
        base = {'a': {'x': 1, 'y': 2}, 'list': [1, 2]}
        over = {'a': {'y': None, 'z': 3}, 'list': [3]}
        with tempfile.TemporaryDirectory() as td:
            p1 = os.path.join(td, 'base.json')
            p2 = os.path.join(td, 'over.json')
            json.dump(base, open(p1, 'w'))
            json.dump(over, open(p2, 'w'))
            p = subprocess.run(
                [sys.executable, 'cfg_merge.py', p1, p2, '--concat-arrays', '--delete-null'],
                capture_output=True, text=True, check=True,
            )
            self.assertEqual(json.loads(p.stdout), {'a': {'x': 1, 'z': 3}, 'list': [1, 2, 3]})


if __name__ == '__main__':
    unittest.main()
